import type { EngineInterface, Register } from 'claude-code'
import { protect, restore } from './protect'
import { SPRITE_H, SPRITE_W, crabSvg } from './sprite'

const MODEL = 'sonnet'
const KEEP = 'KEEP'
const ENABLED_KEY = 'enabled'

// Per-file and total caps on the instruction files sent to the enhancer.
const MAX_FILE_CHARS = 8000
const MAX_MEMORY_CHARS = 24000

const SYSTEM = `You improve prompts a developer typed into Claude Code, a coding agent working in their project.

Rewrite the prompt into a clearer, more specific, actionable instruction to that agent:
- Preserve the user's intent and scope exactly. Do not add goals, features, files, libraries, constraints or acceptance criteria the user did not ask for and the project context does not establish.
- Use the project context (instruction files, skills, tools, recent conversation) only to resolve what the user meant and to follow the project's stated conventions. Mention a skill or tool only when it plainly fits the request.
- Where something is genuinely ambiguous, say what the agent should check or ask, rather than guessing.
- Keep it concise: a short paragraph or a few bullet points. Write it as the user, addressed to the agent.
- Markers like ⟦T1⟧ stand for images, pasted text, links and @-mentions the user attached. Keep every marker exactly as written, each one once, where it belongs in the rewrite. Never invent a marker.

If the prompt is already clear and specific, or is a conversational reply (a yes/no, "continue", a choice between options already offered), output exactly ${KEEP}.

Output only the rewritten prompt or ${KEEP}: no preamble, no quotes, no explanation.`

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'enhance',
      description: 'Show or hide the Enhance prompt button above the prompt',
      argumentHint: '[on|off]',
    })

    return next(e)
  })

  on('command.run', { command: 'enhance' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    const isEnabled =
      arg === 'on' ? true : arg === 'off' ? false : !(await isOn($))
    await $.store.set(ENABLED_KEY, isEnabled)

    return { text: `Enhance prompt button is ${isEnabled ? 'on' : 'off'}.` }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || !(await isOn($))) return next(e)

    const others = await next(e)
    const onPress = () => void enhanceDraft($)

    // The terminal draws the crab in a Client region (crab.ts): animated on its
    // own clock, clicked without a Button's inverse highlight, posting back
    // through `ui.message`. The caption beside it carries the `e` hotkey.
    if (e.surface === 'terminal') {
      const { Box, Button, Client } = $.ui.resolve(e)
      const columns = Math.max(SPRITE_W + 2, Math.min(CRAB_MAX_COLUMNS, e.props.bodyColumns - 26))

      return Box({
        flexDirection: 'column',
        children: [
          Box({
            alignItems: 'center',
            gap: 1,
            children: [
              Client({
                key: CRAB,
                module: './crab.ts',
                props: { busy: isBusy, columns, rows: CRAB_ROWS },
                width: columns,
                height: CRAB_ROWS,
              }),
              Button({
                key: 'enhance',
                plain: true,
                hotkey: 'e',
                dimColor: true,
                label: isBusy ? 'reading your prompt…' : TOOLTIP,
                onPress,
              }),
            ],
          }),
          ...(others ? [others] : []),
        ],
      })
    }

    // Desktop, the editor and mobile draw the same crab as an animated SVG
    // beside the button; the SVG takes no press, so the button is clicked.
    const { Box, Button, Svg } = $.ui.resolve(e)
    const svg = isBusy ? BUSY_SVG : IDLE_SVG

    return Box({
      flexDirection: 'column',
      children: [
        Box({
          key: 'enhance-scope',
          alignItems: 'center',
          gap: 1,
          children: [
            Svg({ source: svg.source, alt: TOOLTIP, width: svg.width, height: svg.height, isInteractive: true }),
            Button({
              key: 'enhance',
              variant: 'primary',
              hotkey: 'e',
              label: isBusy ? 'Reading your prompt…' : TOOLTIP,
              hover: { bold: true },
              onPress,
            }),
          ],
        }),
        ...(others ? [others] : []),
      ],
    })
  })

  // A click on the terminal crab: the Client posts, and it enhances as the
  // button does. The data came from code, so only the one known shape counts.
  on('ui.message', async ($, e, next) => {
    const data = e.data as { action?: unknown } | null
    if (e.element === CRAB && typeof data === 'object' && data?.action === 'enhance') {
      void enhanceDraft($)
    }

    return next(e)
  })
}

const TOOLTIP = 'Enhance my prompt'
const CRAB = 'crab'
const CRAB_ROWS = 6
const CRAB_MAX_COLUMNS = 56
const SVG_SCALE = 3
const svgOf = (busy: boolean) => ({
  source: crabSvg(TOOLTIP, busy, SVG_SCALE),
  width: (SPRITE_W + (busy ? 0 : 20)) * SVG_SCALE,
  height: SPRITE_H * SVG_SCALE,
})
const IDLE_SVG = svgOf(false)
const BUSY_SVG = svgOf(true)

// True while an enhancement runs, so the button can say so and not run twice.
let isBusy = false

// Enhances what is in the prompt box and puts the result back; never sends.
// The flag is claimed before the first await, so a quick second press (a
// double click) is ignored rather than starting a second request.
async function enhanceDraft($: EngineInterface): Promise<void> {
  if (isBusy) return
  isBusy = true
  $.ui.invalidate('ui.render')
  try {
    await enhanceDraftOnce($)
  } finally {
    isBusy = false
    $.ui.invalidate('ui.render')
  }
}

async function enhanceDraftOnce($: EngineInterface): Promise<void> {
  const before = await $.prompt.read()
  const text = before.text.trim()
  if (text === '') {
    $.ui.toast('Type a prompt first, then press Enhance prompt.')

    return
  }

  // Attachments, links and mentions ride through the model as markers, so the
  // rewrite cannot alter or detach them.
  const guarded = protect(text)
  let enhanced: string | undefined
  try {
    enhanced = await enhance($, guarded.text)
  } catch {
    // A request the engine refuses to send rejects; treat it as no rewrite.
    enhanced = undefined
  }

  if (enhanced === undefined) {
    $.ui.toast('Could not enhance this prompt; it was left as typed.')

    return
  }
  const restored = enhanced === KEEP ? undefined : restore(enhanced, guarded.tokens)
  if (restored === undefined || restored.text === text) {
    $.ui.toast('This prompt is already clear; it was left as typed.')

    return
  }
  // Keep anything typed while the model ran: replace only the text we read.
  if ((await $.prompt.read()).text !== before.text) {
    $.ui.toast('The prompt changed while enhancing; it was left as you typed it.')

    return
  }
  const filled = await $.prompt.fill({ text: restored.text, mode: 'replace' })
  if (!filled.isFilled) {
    $.ui.toast('Could not put the enhanced prompt in the box.')
  } else if (restored.readded > 0) {
    $.ui.toast(`Enhanced. ${restored.readded} attachment(s) or link(s) the rewrite left out were added back at the end.`)
  }
}

async function isOn($: EngineInterface): Promise<boolean> {
  return (await $.store.get(ENABLED_KEY)) !== false
}

async function enhance(
  $: EngineInterface,
  text: string,
  signal?: AbortSignal,
): Promise<string | undefined> {
  const context = await gatherContext($)
  const reply = await $.model.complete(
    {
      model: MODEL,
      system: SYSTEM,
      prompt: `${context}\n\n<prompt>\n${text}\n</prompt>`,
      maxTokens: 2000,
      effort: 'low',
      timeoutMs: 45000,
    },
    { signal },
  )

  if (!reply.isAnswered) return undefined
  const out = reply.text.trim()

  return out === '' ? undefined : out
}

async function gatherContext($: EngineInterface): Promise<string> {
  const parts: string[] = [`<cwd>${await $.session.cwd()}</cwd>`]

  const usage = await $.session.usage({ breakdown: 'summary' }).catch(() => undefined)
  const breakdown = usage?.context.breakdown

  let budget = MAX_MEMORY_CHARS
  for (const file of breakdown?.memoryFiles ?? []) {
    if (budget <= 0) break
    const body = await $.fs.read(file.path).catch(() => '')
    if (body.trim() === '') continue
    const clipped = body.slice(0, Math.min(MAX_FILE_CHARS, budget))
    budget -= clipped.length
    parts.push(`<instructions path="${file.path}">\n${clipped}\n</instructions>`)
  }

  const skills = breakdown?.skills?.skillFrontmatter.map(s => s.name) ?? []
  if (skills.length > 0) parts.push(`<skills>${skills.join(', ')}</skills>`)

  const tools = await $.tool.list().catch(() => [])
  if (tools.length > 0) {
    // Built-in tools with a line each; MCP tools by name only, as there can be hundreds.
    const lines = tools
      .filter(t => !t.mcp)
      .map(t => `- ${t.name}: ${firstSentence(t.description)}`)
    const mcp = tools.filter(t => t.mcp).map(t => t.name)
    if (mcp.length > 0) lines.push(`- MCP tools: ${mcp.slice(0, 200).join(', ')}`)
    parts.push(`<tools>\n${lines.join('\n')}\n</tools>`)
  }

  const messages = await $.session.messages().catch(() => [])
  if (Array.isArray(messages) && messages.length > 0) {
    const recent = messages
      .slice(-6)
      .filter(m => m.text.trim() !== '')
      .map(m => `${m.role}: ${m.text.slice(0, 800)}`)
    if (recent.length > 0) {
      parts.push(`<recent_conversation>\n${recent.join('\n\n')}\n</recent_conversation>`)
    }
  }

  return parts.join('\n\n')
}

function firstSentence(text: string): string {
  const line = text.split('\n')[0] ?? ''
  const end = line.search(/\.\s/)

  return (end === -1 ? line : line.slice(0, end + 1)).slice(0, 160)
}

