// Keeps what the person attached to a prompt (pasted images and text, which
// the prompt box holds as `[Image #1]`-style tokens tied to the attachment,
// links, @-mentions) exactly as typed through a rewrite: each is swapped for a
// numbered marker before the model sees the prompt and put back after.

// `[Image #1]`, `[Pasted text #2 +40 lines]` and the like; links; @mentions.
const TOKEN = /\[[^[\]\n]*#\d+[^[\]\n]*\]|\b(?:https?|file|ftp):\/\/[^\s<>"'`)\]]+|(?<=^|\s)@[^\s]+/g
const MARKER = /⟦T(\d+)⟧/g

export type Protected = { text: string; tokens: string[] }

/** The prompt with each attachment, link and mention swapped for ⟦T1⟧, ⟦T2⟧…. */
export function protect(text: string): Protected {
  const tokens: string[] = []
  const swapped = text.replace(TOKEN, token => {
    tokens.push(token)

    return `⟦T${tokens.length}⟧`
  })

  return { text: swapped, tokens }
}

export type Restored = { text: string; readded: number }

/**
 * The rewrite with every marker put back as its original, once each. A marker
 * the model invented is dropped; one it lost is added back on a last line, so
 * nothing the person attached goes missing.
 */
export function restore(rewrite: string, tokens: string[]): Restored {
  const seen = new Set<number>()
  let text = rewrite.replace(MARKER, (_, n: string) => {
    const i = Number(n) - 1
    const token = tokens[i]
    if (token === undefined || seen.has(i)) return ''
    seen.add(i)

    return token
  })
  const missing = tokens.filter((_, i) => !seen.has(i))
  if (missing.length > 0) text = `${text.trimEnd()}\n\n${missing.join(' ')}`

  return { text: text.replace(/[ \t]+\n/g, '\n').trim(), readded: missing.length }
}

