// The librarian Clawd: Claude Code's classic 8-bit crab (square body, small
// eyes, arms out, four legs) in a little librarian's cap, carrying a book,
// drawn pose by pose so it can walk, blink, wave and read. The terminal draws
// its pixels as half-block cells (crab.ts), every other surface as an animated
// SVG (crabSvg); both come from drawCrab.

export const SPRITE_W = 16
export const SPRITE_H = 10

const C = {
  body: '#D97757',
  shade: '#B9583B',
  eye: '#1A1412',
  cap: '#7A3B5E',
  band: '#5A2A45',
  gold: '#E8C15A',
  cover: '#3E6AA8',
  spine: '#294B7E',
  page: '#F5EEDC',
  ink: '#B7AA90',
} as const

/** Rows of pixels, `undefined` clear. */
export type Pixels = (string | undefined)[][]

export type Pose = {
  /** Which pair of legs is lifted mid-step; absent, all four stand. */
  legs?: 0 | 1
  blink?: boolean
  /** Where the eyes look, left to right. */
  look?: -1 | 0 | 1
  /** The free claw raised in a hello. */
  wave?: boolean
  /** The book held open in front, read; `page` is a page mid-turn. */
  reading?: boolean
  page?: 0 | 1 | 2
}

export function blank(width: number, height: number): Pixels {
  return Array.from({ length: height }, () => Array<string | undefined>(width).fill(undefined))
}

export function drawCrab(pose: Pose = {}): Pixels {
  const px = blank(SPRITE_W, SPRITE_H)
  const rect = (x: number, y: number, w: number, h: number, c: string | undefined) => {
    for (let j = y; j < y + h; j++) {
      const row = px[j]
      if (!row) continue
      for (let i = x; i < x + w; i++) if (i >= 0 && i < SPRITE_W) row[i] = c
    }
  }
  const dot = (x: number, y: number, c: string | undefined) => rect(x, y, 1, 1, c)
  const X = 1 // the body's left edge, leaving room for a raised claw
  const Y = 2 // the body's top row, under the cap

  // Four legs; mid-step, every other one is a pixel shorter.
  ;[X + 2, X + 4, X + 7, X + 9].forEach((x, i) => {
    rect(x, Y + 6, 1, pose.legs !== undefined && i % 2 === pose.legs ? 1 : 2, C.body)
  })

  // The square body, arms straight out, a shade along the bottom.
  rect(X + 2, Y, 8, 6, C.body)
  rect(X, Y + 3, 12, 2, C.body)
  rect(X + 2, Y + 5, 8, 1, C.shade)
  dot(X + 9, Y + 5, C.shade)

  // A hello: the left arm up instead of out.
  if (pose.wave) {
    rect(X, Y + 3, 2, 2, undefined)
    rect(X, Y, 2, 3, C.body)
  }

  // Small eyes, one pixel wide.
  const look = pose.look ?? 0
  for (const ex of [X + 3, X + 8]) {
    if (pose.blink) dot(ex + look, Y + 2, C.eye)
    else rect(ex + look, Y + 1, 1, 2, C.eye)
  }

  // The librarian's cap with a gold button.
  rect(X + 3, Y - 2, 6, 1, C.cap)
  rect(X + 2, Y - 1, 8, 1, C.band)
  dot(X + 5, Y - 2, C.gold)

  if (pose.reading) {
    // The book open in front, held by both claws, a page turning.
    rect(X + 2, Y + 3, 4, 2, C.page)
    rect(X + 6, Y + 3, 4, 2, C.page)
    rect(X + 1, Y + 5, 10, 1, C.cover)
    rect(X + 3, Y + 3, 2, 1, C.ink)
    rect(X + 7, Y + 3, 2, 1, C.ink)
    if (pose.page === 1) rect(X + 6, Y + 4, 3, 1, C.ink)
    if (pose.page === 2) rect(X + 3, Y + 4, 3, 1, C.ink)
  } else {
    // The book carried in the right claw: cover, spine, gold label, pages.
    rect(X + 12, Y + 1, 3, 4, C.cover)
    rect(X + 12, Y + 1, 1, 4, C.spine)
    dot(X + 13, Y + 2, C.gold)
    rect(X + 13, Y + 5, 2, 1, C.page)
  }

  return px
}

/** One terminal cell: a glyph, its color and the color behind it. */
export type Cell = { ch: string; fg?: string; bg?: string; bold?: boolean }

/**
 * Pixels as half-block cells, two pixel rows to a text row: `▀` paints the
 * top pixel over the bottom one as the background, `▄` the bottom alone.
 */
export function halfBlocks(px: Pixels): Cell[][] {
  const width = Math.max(0, ...px.map(row => row.length))
  const rows: Cell[][] = []
  for (let y = 0; y < px.length; y += 2) {
    const cells: Cell[] = []
    for (let x = 0; x < width; x++) {
      const top = px[y]?.[x]
      const bottom = px[y + 1]?.[x]
      if (top === undefined && bottom === undefined) cells.push({ ch: ' ' })
      else if (top === undefined) cells.push({ ch: '▄', fg: bottom })
      else if (bottom === undefined) cells.push({ ch: '▀', fg: top })
      else if (top === bottom) cells.push({ ch: '█', fg: top })
      else cells.push({ ch: '▀', fg: top, bg: bottom })
    }
    rows.push(cells)
  }

  return rows
}

/** Copies `sprite` onto `canvas` at (x, y), its clear pixels left alone. */
export function stamp(canvas: Pixels, sprite: Pixels, x: number, y: number): void {
  sprite.forEach((row, j) =>
    row.forEach((c, i) => {
      const target = canvas[y + j]
      if (c !== undefined && target && x + i >= 0 && x + i < target.length) target[x + i] = c
    }),
  )
}

// Pixels as SVG rects, each horizontal run of one color one rect.
function rects(px: Pixels): string {
  const out: string[] = []
  px.forEach((row, y) => {
    let x = 0
    while (x < row.length) {
      const c = row[x]
      let end = x + 1
      while (end < row.length && row[end] === c) end++
      if (c !== undefined) out.push(`<rect x="${x}" y="${y}" width="${end - x}" height="1" fill="${c}"/>`)
      x = end
    }
  })

  return out.join('')
}

// A flip-book of `frames`, each shown for `ms` in turn, as CSS keyframes.
function flipBook(frames: Pixels[], ms: number, name: string): { css: string; svg: string } {
  const n = frames.length
  const pct = (k: number) => `${((100 * k) / n).toFixed(3)}%`
  const css = frames
    .map(
      (_, k) =>
        `@keyframes ${name}${k}{0%{opacity:${k === 0 ? 1 : 0}}${pct(k)}{opacity:1}${pct(k + 1)}{opacity:0}}` +
        `.${name}${k}{opacity:0;animation:${name}${k} ${n * ms}ms steps(1,end) infinite}`,
    )
    .join('')
  const svg = frames.map((f, k) => `<g class="f ${name}${k}">${rects(f)}</g>`).join('')

  return { css, svg }
}

/**
 * The crab as an animated SVG: strolling back and forth, stepping and
 * blinking while idle and stopping to wave while hovered; reading its book,
 * eyes moving and pages turning, while `busy`.
 */
export function crabSvg(title: string, busy: boolean, scale = 3): string {
  const walk = busy ? 0 : 20
  const width = SPRITE_W + walk
  const step = (legs: 0 | 1, blink = false) => drawCrab({ legs, blink })
  const book = busy
    ? flipBook(
        [
          drawCrab({ reading: true, look: -1 }),
          drawCrab({ reading: true, look: 0 }),
          drawCrab({ reading: true, look: 1, page: 1 }),
          drawCrab({ reading: true, look: 1, page: 2 }),
          drawCrab({ reading: true, look: 0, blink: true }),
        ],
        320,
        'r',
      )
    : flipBook([step(0), step(1), step(0), step(1), step(0), step(1), step(0, true), step(1)], 180, 'w')
  const hello = busy ? '' : `<g class="hi">${rects(drawCrab({ wave: true, look: -1 }))}</g>`
  const css = [
    book.css,
    busy ? '' : `.walk{animation:walk 7s ease-in-out infinite alternate}@keyframes walk{to{transform:translateX(${walk}px)}}`,
    '.hi{opacity:0}',
    'svg:hover .walk,svg:hover .f{animation-play-state:paused}',
    busy ? '' : 'svg:hover .frames{opacity:0}svg:hover .hi{opacity:1}',
  ].join('')

  return [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${SPRITE_H}"`,
    ` width="${width * scale}" height="${SPRITE_H * scale}" shape-rendering="crispEdges">`,
    `<title>${title}</title><style>${css}</style>`,
    `<g class="walk"><g class="frames">${book.svg}</g>${hello}</g></svg>`,
  ].join('')
}

