// The terminal's librarian crab: a Client surface module, so it animates on
// the frame clock and takes clicks without being a Button (a Button inverts
// under the pointer). It strolls while waiting, stops to wave when hovered,
// and reads its book while `busy`. A click on it posts `{ action: 'enhance' }`.
import type { ClientModule, ClientSurface } from 'claude-code'
import { SPRITE_H, SPRITE_W, blank, drawCrab, halfBlocks, stamp } from './sprite'
import type { Cell, Pixels, Pose } from './sprite'

export type CrabProps = { busy: boolean; columns: number; rows: number }
type CrabState = { t: number; x: number; dir: 1 | -1; rest: number; hover: boolean; down: boolean }

const TICK_MS = 110
const BUBBLE = '‹ Enhance my prompt!'
const INITIAL: CrabState = { t: 0, x: 0, dir: 1, rest: 0, hover: false, down: false }

// The latest props per instance, for the clock's callback (it outlives a call).
const latest = new WeakMap<object, CrabProps>()

const Crab: ClientModule<CrabProps, CrabState> = (props, surface) => {
  latest.set(surface, props)
  if (surface.state === undefined) start(surface)
  const s = surface.state ?? INITIAL
  const { Box, Text } = surface.elements
  const width = Math.max(SPRITE_W, surface.columns || props.columns)
  const rows = Math.max(Math.ceil(SPRITE_H / 2), surface.rows || props.rows)

  const canvas = blank(width, rows * 2)
  const x = Math.min(s.x, width - SPRITE_W)
  const sprite = drawCrab(poseOf(s, props.busy))
  stamp(canvas, !props.busy && !s.hover && s.dir < 0 ? mirror(sprite) : sprite, x, rows * 2 - SPRITE_H)
  const cells = halfBlocks(canvas)

  if (props.busy) {
    // Sparkles over the head while it reads.
    const twinkle = (s.t >> 2) % 2 === 0
    write(cells, 0, x + (twinkle ? 2 : 12), twinkle ? '+' : '·', '#E8C15A')
    write(cells, 0, x + (twinkle ? 13 : 4), twinkle ? '·' : '+', '#E8C15A')
  } else if (s.hover) {
    // The tooltip, as a speech bubble beside the crab.
    const right = x + SPRITE_W + 1
    const at = right + BUBBLE.length <= width ? right : Math.max(0, x - BUBBLE.length - 1)
    const text = right + BUBBLE.length <= width ? BUBBLE : `${BUBBLE.slice(2)} ›`
    write(cells, Math.max(0, rows - 4), at, text, '#EB9A7E', true)
  }

  return Box({
    flexDirection: 'column',
    children: cells.map(row => Text({ children: runs(row).map(run => draw(Text, run)) })),
  })
}

export default Crab

function start(surface: ClientSurface<CrabState>): void {
  surface.setState(INITIAL)
  surface.every(TICK_MS, () => {
    const s = surface.state
    const props = latest.get(surface)
    if (s && props) surface.setState(tick(s, props, surface.columns || props.columns))
  })
  surface.onPointer(e => {
    const s = surface.state ?? INITIAL
    const props = latest.get(surface)
    const width = surface.columns || props?.columns || SPRITE_W
    const left = Math.min(s.x, width - SPRITE_W)
    const isOver = e.x >= left && e.x < left + SPRITE_W && e.y >= 0
    if (e.type === 'down') {
      if (e.button === 'left' && isOver) surface.setState({ ...s, down: true, hover: true })
    } else if (e.type === 'up') {
      if (s.down) {
        surface.setState({ ...s, down: false })
        if (isOver) surface.post({ action: 'enhance' })
      }
    } else if (e.type === 'leave') {
      if (s.hover || s.down) surface.setState({ ...s, hover: false, down: false })
    } else if (isOver !== s.hover) {
      surface.setState({ ...s, hover: isOver })
    }
  })
  surface.onKey(e => {
    if (e.key === 'return' || e.key === ' ') surface.post({ action: 'enhance' })
  })
}

// One step of the clock: stroll a column every other tick, pausing to look
// around at each end and now and then on the way; stand still while hovered
// or reading.
function tick(s: CrabState, props: CrabProps, width: number): CrabState {
  const t = s.t + 1
  if (props.busy || s.hover) return { ...s, t }
  if (s.rest > 0) return { ...s, t, rest: s.rest - 1 }
  if (t % 2 === 1) return { ...s, t }
  const maxX = Math.max(0, width - SPRITE_W)
  const x = Math.min(maxX, Math.max(0, s.x + s.dir))
  if (x === 0 || x === maxX) return { ...s, t, x, dir: x === 0 ? 1 : -1, rest: 14 }

  return { ...s, t, x, rest: t % 90 === 0 ? 12 : 0 }
}

function poseOf(s: CrabState, busy: boolean): Pose {
  const blink = s.t % 32 === 0
  if (busy) {
    const look = ([-1, 0, 1, 0] as const)[(s.t >> 2) % 4]
    const page = ((s.t >> 3) % 3) as 0 | 1 | 2

    return { reading: true, look, page, blink }
  }
  if (s.hover) return { wave: (s.t >> 2) % 2 === 0, look: -1, blink }
  if (s.rest > 0) return { look: ([-1, 0, 1, 0] as const)[(s.t >> 3) % 4], blink }

  return { legs: ((s.t >> 1) % 2) as 0 | 1, look: 1, blink }
}

function mirror(px: Pixels): Pixels {
  return px.map(row => [...row].reverse())
}

function write(cells: Cell[][], row: number, col: number, text: string, color: string, bold = false): void {
  const line = cells[row]
  if (!line) return
  ;[...text].forEach((ch, i) => {
    if (col + i >= 0 && col + i < line.length) line[col + i] = { ch, fg: color, bold }
  })
}

// Adjacent cells drawn alike, merged into one run.
function runs(row: Cell[]): Cell[] {
  const out: Cell[] = []
  for (const cell of row) {
    const last = out[out.length - 1]
    if (last && last.fg === cell.fg && last.bg === cell.bg && !!last.bold === !!cell.bold) last.ch += cell.ch
    else out.push({ ...cell })
  }

  return out
}

function draw(Text: ClientSurface['elements']['Text'], run: Cell) {
  if (run.fg === undefined && run.bg === undefined) return run.ch

  return Text({
    ...(run.fg === undefined ? {} : { color: run.fg }),
    ...(run.bg === undefined ? {} : { backgroundColor: run.bg }),
    ...(run.bold ? { bold: true } : {}),
    children: [run.ch],
  })
}

